insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 1, 21, 'Porque a profecia jamais foi produzida pela vontade humana, mas os santos homens de Deus falaram conduzidos pelo Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 1, 'E também houve falsos profetas entre o povo, assim como também haverá falsos instrutores entre vós, que disfarçadamente introduzirão heresias de perdição, e negarão ao Senhor que os comprou, trazendo sobre eles mesmos repentina destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 2, 'Muitos seguirão suas perdições, e por meio deles o caminho da verdade será insultado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 3, 'E por ganância, eles vos farão de mercadoria com palavras falsamente inventadas; sobre os quais desde muito tempo não está a condenação sem efeito, e sua perdição não cochila.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 4, 'Porque se Deus não perdoou aos anjos que pecaram, em vez disso lançando-os no inferno, entregou-os às cadeias da escuridão, tendo sido reservados para o julgamento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 5, 'Nem perdoou ao mundo antigo, mas guardou a Noé, anunciador da justiça, com outros sete, trazendo o dilúvio sobre o mundo dos ímpios;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 6, 'E condenou as cidades de Sodoma e Gomorra à destruição, reduzindo-as a cinza, e pondo-as como exemplo para os que vivessem impiamente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 7, 'E livrou ao justo Ló, [que estava] cansado do corrupto modo de viver dos maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 8, '(Porque, [enquanto] aquele justo habitava entre eles, todo dia ele atormentava sua justa alma, ao ver e ouvir as [suas] injustas obras).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 9, '[Assim] o Senhor sabe livrar os devotos das tentações, e reservar aos injustos para o dia do julgamento, para serem punidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 10, 'Porém principalmente aos que segundo a carne andam em mau desejo de impureza, e desprezam as autoridades; atrevidos, agradando a si mesmos, não tendo medo de insultar as [coisas dignas de] glórias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 11, 'Ainda que [até] os anjos, sendo maiores em força e poder, não trazem juízo insultuoso contra elas diante do Senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 12, 'Mas estes, como animais irracionais, que seguem a natureza, gerados para a prisão e destruição, insultando aquilo que não entendem, perecerão na sua própria corrupção;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 13, 'recebendo o pagamento da injustiça, tendo como prazer seus maus desejos durante o dia, sendo manchas e defeitos, tendo prazer em seus enganos, participando do banquete convosco;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 14, 'tendo os olhos cheios de adultério, e nunca parando de pecar; iludindo as almas inconstantes, tendo o coração exercitado na ganância, filhos da maldição;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 15, 'os quais, havendo deixado o caminho direito, desviaram-se, seguindo o caminho de Balaão, [filho] de Bosor, que amou o pagamento da injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 16, 'Mas ele teve a repreensão de sua transgressão; o mudo animal de jugo, falando em voz humana, impediu a loucura do profeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 17, 'Estes são fontes sem água, nuvens levadas pela tempestade; para os quais a escuridão das trevas está reservada para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 18, 'Porque ao falarem coisas muito arrogantes de vaidade, iludem com os maus desejos da carne, [e] com perversões, aqueles que já tinham realmente escapado dos que andam no erro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 19, 'Prometendo-lhes liberdade, [mas] sendo eles mesmos servos da corrupção; porque aquele de quem alguém é vencido, do tal também se faz servo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 20, 'Porque se, por causa do conhecimento do Senhor e Salvador Jesus Cristo, tiverem escapado das imundícies do mundo, e novamente se envolverem nelas, e forem vencidos, o fim será pior que o começo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 21, 'Porque melhor teria lhes sido se não tivessem conhecido o caminho da justiça do que, depois de conhecerem, terem se desviado do santo mandamento que havia lhes sido entregue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 2, 22, 'Mas isto lhes sobreveio [conforme] um verdadeiro provérbio, [que diz] : O cão voltou ao seu próprio vômito; e a porca lavada [voltou] ao chiqueiro da lama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 1, 'Amados, eu já vos escrevo esta segunda carta, em [ambas] as quais eu desperto vosso sincero entendimento por meio da relembrança;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 2, 'Para que vos lembreis das palavras que anteriormente foram ditas pelos santos profetas, e do nosso mandamento, dos apóstolos do Senhor e Salvador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 3, 'Sabendo primeiro isto: que nos últimos dias virão escarnecedores, andando segundo seus próprios maus desejos,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 4, 'E dizendo: Onde está a promessa da vinda dele? Pois desde que os pais dormiram, todas as coisas continuam como desde o princípio da criação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 5, 'Porque eles ignoram isto por sua própria vontade, que pela palavra de Deus desde os [tempos] antigos [é que] foram os céus, e [que] a terra [saiu] da água, e sobre a água continua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 6, 'Pelas quais o mundo anterior foi destruído, coberto com as águas do dilúvio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 7, 'E os céus e a terra de agora, pela mesma palavra estão reservados, e são guardados para o fogo até o dia do juízo, e da perdição das pessoas ímpias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 8, 'Mas amados, desta uma coisa não ignoreis: que um dia para o Senhor [é] como mil anos, e mil anos como um dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 9, 'O Senhor não é tardio [em sua] promessa (como alguns [a] consideram tardia); mas ele é paciente para conosco, não querendo que alguns pereçam, mas sim que todos venham ao arrependimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 10, 'Mas o dia do Senhor virá como um ladrão durante a noite, no qual os céus se desfarão com grande estrondo, e os elementos queimando se dissolverão, e a terra e as obras que nela [há] serão queimadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 11, 'Visto, pois, que todas estas coisas estão para serem desfeitas, de que maneira vós deveis ser em santo comportamento e piedade,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 12, 'esperando, e tendo pressa para a vinda do dia de Deus, pelo qual os céus, incendiados, se desfarão, e os elementos, inflamados, se derreterão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 13, 'Porém, segundo a sua promessa, aguardamos novos céus e nova terra, em que a justiça habita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 14, 'Por isso, amados, aguardando essas coisas, procurai que por ele sejais achados incontaminados e irrepreensíveis em paz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 15, 'E considerai como salvação a paciência de nosso Senhor; assim como também nosso irmão Paulo vos escreveu, segundo a sabedoria que lhe foi dada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 16, 'Como também em duas as [suas] cartas, ele fala nelas destas coisas; entre as quais há algumas coisas difíceis de entender, as quais os ignorantes e os inconstantes distorcem, assim como também as outras Escrituras, para a própria perdição deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 17, 'Portanto vós, amados, sabendo [disto] com antecedência, guardai-vos para que, pelo engano dos maus, não sejais juntamente arrebatados, e caiais de vossa firmeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 61, '2 Pedro', '2Pe', 3, 18, 'Mas crescei em graça e conhecimento de nosso Senhor e Salvador Jesus Cristo. A ele seja a glória, tanto agora como no dia da eternidade, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 1, 'O que era desde o princípio, o que ouvimos, o que vimos com os nossos olhos, o que temos contemplado, e nossas mãos tocaram, quanto à Palavra da vida,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 2, '(pois a vida já foi manifesta, e nós a vimos, demos testemunho, e vos anunciamos a vida eterna, que estava com o Pai, e a nós foi manifesta)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 3, 'o que vimos e ouvimos, isso vos anunciamos, para que também vós tenhais comunhão conosco. E a nossa comunhão [é] com o Pai, e com o seu Filho Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 4, 'Estas coisas vos escrevemos para que a vossa alegria seja completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 5, 'E esta é a mensagem que dele ouvimos, e vos anunciamos: que Deus é luz, e não há nele nada de trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 6, 'Se dissermos que temos comunhão com ele, e andarmos em trevas, mentimos, e não praticamos a verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 7, 'Porém, se andamos na luz, como ele está na luz, temos comunhão uns com os outros, e o sangue de Jesus Cristo, seu Filho, nos purifica de todo pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 8, 'Se dissermos que não temos pecado, enganamos a nós mesmos, e a verdade não está em nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 9, 'Se confessarmos nossos pecados, ele é fiel e justo para nos perdoar os pecados e nos purificar de toda injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 1, 10, 'Se dissermos que não pecamos, nós o fazemos de mentiroso, e a palavra dele não está em nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 1, 'Meus filhinhos, vos escrevo estas coisas para que não pequeis; mas se alguém pecar, temos um advogado com o Pai: Jesus Cristo, o justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 2, 'E ele é o sacrifício para perdão dos nossos pecados; e não somente dos nossos, mas também dos de todo o mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 3, 'E nisto sabemos que o conhecemos, se guardamos os seus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 4, 'Aquele que diz: “Eu o conheço”, mas não guarda os seus mandamentos, é mentiroso, e nele não está a verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 5, 'Mas quem guarda a sua palavra, nele verdadeiramente o amor de Deus tem se aperfeiçoado; nisso sabemos que estamos nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 6, 'Aquele que diz que está nele também deve andar como ele andou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 7, 'Irmãos, não vos escrevo um mandamento novo, mas sim o mandamento antigo, que tivestes desde o princípio. Este mandamento antigo é a palavra que ouvistes desde o princípio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 8, 'Mas também vos escrevo um mandamento novo, que é verdadeiro nele e em vós; pois as trevas passaram, e a verdadeira luz já ilumina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 9, 'Aquele que diz que está na luz, e odeia seu irmão, até agora está nas trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 10, 'Aquele que ama o seu irmão está na luz, e nele não há motivo algum de tropeço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 11, 'Mas aquele que odeia seu irmão está nas trevas, anda nas trevas, e não sabe para onde vai, pois as trevas lhe cegaram os olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 12, 'Eu vos escrevo, filhinhos, porque pelo nome dele os vossos pecados são perdoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 13, 'Eu vos escrevo, pais, porque conheceis aquele que é desde o princípio. Eu vos escrevo, jovens, porque vencestes o maligno. Eu vos escrevo, filhinhos, porque conheceis o Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 14, 'Eu vos escrevi, pais, porque conheceis aquele que é desde o princípio. Eu vos escrevi, jovens, porque sois fortes, a palavra de Deus está em vós, e vencestes o maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 15, 'Não ameis o mundo, nem as coisas que há no mundo. Se alguém ama o mundo, o amor do Pai não está nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 16, 'Pois tudo o que há no mundo, a cobiça da carne, a cobiça dos olhos, e a ostentação da vida, não é do Pai, mas do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 17, 'O mundo passa, e também a sua cobiça; mas aquele que faz a vontade de Deus permanece para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 18, 'Filhinhos, é a última hora. E como ouvistes que o anticristo vem, já agora muitos anticristos chegaram. Por isso sabemos que é a última hora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 19, 'Eles saíram de nós, mas não eram dos nossos, pois se fossem dos nossos, continuariam conosco; mas [o que aconteceu] foi para tornar claro que todos eles não eram dos nossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 20, 'Vós, porém, tendes a unção do Santo, e conheceis todas as coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 21, 'Eu vos escrevi, não porque não conheceis a verdade, mas sim, porque a conheceis, e porque nenhuma mentira vem da verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 22, 'Quem é o mentiroso, senão aquele que nega que Jesus é o Cristo? Esse é o anticristo, que nega o Pai e o Filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 23, 'Quem nega o Filho também não tem o Pai; aquele que confessa o filho também tem o Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 24, 'Portanto o que ouvistes desde o princípio permaneça em vós. Se o que ouvistes desde o princípio permanecer em vós, também permanecereis no Filho e no Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 25, 'E esta é a promessa que ele nos prometeu: a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 26, 'Estas coisas vos escrevi acerca dos que vos tentam vos enganar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 27, 'E a unção que recebeste dele continua em vós, e não tendes necessidade de que alguém vos ensine; mas, como a mesma unção vos ensina tudo, e é verdadeira, e não mentira, e como ela vos ensinou, [assim] nele permanecereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 28, 'E agora, filhinhos, permanecei nele; a fim de que, quando ele se manifestar, tenhamos confiança, e não sejamos envergonhados diante dele na sua vinda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 2, 29, 'Se sabeis que ele é justo, sabeis que todo aquele que pratica a justiça é nascido dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 1, 'Vede quão grande amor o Pai tem nos dado, que fôssemos chamados filhos de Deus. Por isso o mundo não nos conhece, pois não conhece a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 2, 'Amados, agora somos filhos de Deus, e ainda não está manifesto o que seremos. Porém sabemos que, quando ele se manifestar, seremos semelhantes a ele, pois o veremos como ele é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 3, 'E todo aquele que tem nele essa esperança purifica a si mesmo, como também ele é puro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 4, 'Todo aquele que pratica o pecado também pratica injustiça, pois o pecado é injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 5, 'E sabeis que ele apareceu para tirar os nossos pecados; e nele não há pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 6, 'Todo aquele que nele permanece não pratica o pecado; todo aquele que costuma pecar não o viu nem o conheceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 7, 'Filhinhos, ninguém vos engane. Quem pratica a justiça é justo, assim como ele é justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 8, 'Quem pratica o pecado é do diabo, pois o diabo peca desde o princípio. Para isto o Filho de Deus se manifestou, para desfazer as obras do diabo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 9, 'Todo aquele que é nascido de Deus não pratica o pecado, pois a sua semente reside nele; e não pode praticar o pecado, porque é nascido de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 10, 'Nisto são reconhecíveis os filhos de Deus, e os filhos do diabo: todo aquele que não pratica a justiça, e não ama o seu irmão, não é de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 11, 'Pois esta é a mensagem que ouvistes desde o princípio: que nos amemos uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 12, 'Não [sejamos] como Caim, [ que] era do maligno, e matou o seu irmão. E por que o matou? Porque as suas obras eram más, e as do seu irmão justas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 13, 'Meus irmãos, não vos surpreendeis se o mundo vos odeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 14, 'Nós sabemos que já passamos da morte para a vida, pois amamos os irmãos. Quem não ama[seu] irmão permanece na morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 15, 'Todo aquele que odeia o seu irmão é homicida. E sabeis que nenhum homicida tem a vida eterna habitando nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 16, 'Nisto conhecemos o amor: ele deu a sua vida por nós. E nós devemos dar as [nossas] vidas pelos irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 17, 'Se alguém tiver bens do mundo, e vir o seu irmão em necessidade, e não se compadecer dele, como pode o amor de Deus estar nele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 18, 'Meus filhinhos, amemos não de palavra, nem de língua, mas sim com ação e verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 19, 'E nisto sabemos que somos da verdade, e teremos segurança nos nossos corações diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 20, 'Pois, se o nosso coração [nos] condena, maior é Deus que o nosso coração, e conhece tudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 21, 'Amados, se nosso coração não nos condena, temos confiança diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 22, 'E qualquer coisa que pedirmos, dele receberemos; porque guardamos os seus mandamentos, e fazemos o que lhe agrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 23, 'E este é o seu mandamento: que creiamos no nome do seu Filho Jesus Cristo, e nos amemos uns aos outros, como ele nos mandou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 3, 24, 'E a pessoa que guarda os seus mandamentos está nele, e ele nela. E nisto sabemos que ele está em nós: pelo Espírito que ele nos deu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 1, 'Amados, não creiais em todo espírito, mas provai se os espíritos são da parte de Deus; porque muitos falsos profetas têm vindo ao mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 2, 'Nisto conhecereis o Espírito de Deus: todo espírito que confessa que Jesus Cristo veio em carne é de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 3, 'e todo espírito que não confessa que Jesus Cristo veio em carne não é de Deus; e este é o do anticristo, do qual já ouvistes que virá, e que já agora está no mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 4, 'Filhinhos, vós sois de Deus, e tendes vencido esses; pois maior é o que está em vós do que o que está no mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 5, 'Eles são do mundo, por isso falam do mundo, e o mundo os ouve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 6, 'Nós somos de Deus. Aquele que conhece Deus ouve-nos; aquele que não é de Deus não nos ouve. Nisto conhecemos o Espírito da verdade e o espírito do erro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 7, 'Amados, nos amemos uns aos outros; porque o amor é de Deus, e todo aquele que ama é nascido de Deus e conhece a Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 8, 'Aquele que não ama não conhece a Deus, porque Deus é amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 9, 'Nisto se manifestou o amor de Deus por nós: que Deus enviou o seu Filho unigênito ao mundo, para que por meio dele vivamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 10, 'Nisto está o amor, não que nós tenhamos amado a Deus, mas sim, que ele nos amou, e enviou seu Filho como sacrifício para perdão dos nossos pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 11, 'Amados, se Deus assim nos amou, também nós devemos amar uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 12, 'Ninguém jamais viu Deus; se nos amamos uns aos outros, Deus está em nós, e o amor dele em nós é aperfeiçoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 13, 'Nisto sabemos que estamos nele, e ele em nós, porque ele nos deu do seu Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 14, 'E vimos e damos testemunho de que o Pai enviou o Filho [para ser] Salvador do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 15, 'Todo aquele que confessar que Jesus é o Filho de Deus, Deus está nele, e ele em Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 16, 'E nós conhecemos e cremos no amor que Deus tem por nós. Deus é amor, e quem está no amor está em Deus, e Deus nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 17, 'Nisto o amor é aperfeiçoado em nós, para que no dia do juízo tenhamos confiança, pois, como ele é, assim somos nós neste mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 18, 'No amor não há medo; pelo contrário, o perfeito amor expulsa o medo; pois o medo está relacionado ao castigo; e o que teme não está aperfeiçoado em amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 19, 'Nós o amamos, porque ele nos amou primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 20, 'Se alguém diz: “Eu amo a Deus”, e odeia seu irmão, é mentiroso. Pois quem não ama seu irmão, ao qual viu, como pode amar a Deus, a quem nunca viu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 4, 21, 'E dele temos este mandamento: quem ama a Deus, ame também seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 1, 'Todo aquele que crê que Jesus é o Cristo é nascido de Deus; e todo aquele que ama ao que gerou, também ama ao que dele é nascido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 2, 'Nisto sabemos que amamos os filhos de Deus: quando amamos a Deus, e guardamos os seus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 3, 'Pois este é o amor de Deus: que guardemos os seus mandamentos. E os seus mandamentos não são pesados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 4, 'Pois todo aquele que é nascido de Deus vence o mundo; e esta é a vitória que vence o mundo: a nossa fé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 5, 'Quem é o que vence o mundo, senão aquele que crê que Jesus é o Filho de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 6, 'Este é aquele que veio por água e sangue: Jesus, o Cristo. Não só pela água, mas pela água e [pelo] sangue. E o Espírito é o que lhe dá testemunho, porque o Espírito é a verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 7, 'Pois são três os que dão testemunho no céu: o Pai, a Palavra, e o Espírito Santo; e estes três são um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 8, 'E três são os que testemunham na terra: o Espírito, a água e o sangue; e estes três estão em unidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 9, 'Se recebemos o testemunho humano, o testemunho de Deus é maior; pois este é o testemunho de Deus, que testificou de seu Filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 10, 'Quem crê no Filho de Deus tem testemunho em si mesmo; quem não crê em Deus o fez de mentiroso, porque não creu no testemunho que Deus deu acerca do seu Filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 11, 'E este é o testemunho: que Deus nos deu a vida eterna; e essa vida está no seu Filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 12, 'Quem tem o Filho tem a vida; quem não tem o Filho de Deus não tem a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 13, 'Estas coisas escrevi para vós que credes no nome do Filho de Deus, para que saibais que tendes a vida eterna, e que creiais no nome do Filho de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 14, 'E esta é a confiança que diante dele: que se pedirmos alguma coisa conforme a sua vontade, ele nos ouve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 15, 'E se sabemos que nos ouve em tudo o que pedimos, sabemos que alcançamos as coisas que lhe pedimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 16, 'Se alguém vê o seu irmão cometer um pecado que não é para a morte, orará, e lhe dará vida, para os que não pecarem para a morte. Há pecado para a morte, pelo qual não digo que ore.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 17, 'Toda injustiça é pecado; e há pecado que não é para a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 18, 'Sabemos que todo aquele que é nascido de Deus não pratica o pecado; mas o que é gerado de Deus guarda a si mesmo, e o maligno não o toca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 19, 'Sabemos que somos de Deus, e que o mundo todo jaz no maligno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 20, 'E sabemos que o Filho de Deus veio, e nos deu entendimento para conhecermos o Verdadeiro; e no Verdadeiro estamos, em seu Filho Jesus Cristo. Este é o verdadeiro Deus, e a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 62, '1 João', '1Jo', 5, 21, 'Filhinhos, guardai-vos dos ídolos. Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 1, 'O ancião, à senhora eleita, e a seus filhos, aos quais eu amo em verdade; e não somente eu, mas também todos os que têm conhecido a verdade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 2, 'Por causa da verdade que está em nós, e estará para sempre conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 3, 'Graça, misericórdia, [e] paz de Deus Pai, e do Senhor Jesus Cristo, o Filho do Pai, seja convosco em verdade e amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 4, 'Muito me alegrei por eu ter encontrado [alguns] de teus filhos andando na verdade, assim como recebemos o mandamento do Pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 5, 'E agora, senhora, eu te rogo, não como te escrevendo um novo mandamento, mas o que tivemos desde o princípio: que nos amemos uns aos outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 6, 'E este é o amor: que andemos segundo seus mandamentos. E este é o mandamento, como [já] ouvistes desde o princípio: que nele andeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 7, 'Porque muitos enganadores têm surgido no mundo que não declaram que Jesus Cristo veio em carne. Este é o enganador e o anticristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 8, 'Vigiai por vós mesmos, para que não percamos o que trabalhamos; mas sim que recebamos uma recompensa completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 9, 'Todo aquele que transgride e não continua na doutrina de Cristo não tem a Deus; quem continua na doutrina de Cristo tem tanto ao Pai quanto ao Filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 10, 'Se alguém vem a vós, e não traz esta doutrina, não recebais em [vossa] casa, nem o saudeis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 11, 'Porque quem o saúda compartilha com suas más obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 12, 'Eu tenho muitas coisas para vos escrever, porém não quis [fazê-lo] com papel e tinta; mas espero vir até vós, e falar [convosco] face a face, para que a nossa alegria seja completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 63, '2 João', '2Jo', 1, 13, 'Os filhos de tua irmã, a eleita, te saúdam. Amém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 1, 'O ancião, ao amado Gaio, a quem amo em verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 2, 'Amado, eu desejo que estejas bem em todas as coisas, e que tenhas saúde, assim como bem está a tua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 3, 'Pois muito me alegrei quando irmãos chegaram, e testemunharam da tua verdade, como tu andas na verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 4, 'Não tenho maior alegria do que esta: [a de] ouvir que meus filhos andam na verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 5, 'Amado, tu ages fielmente em tudo o que fazes aos irmãos, inclusive aos forasteiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 6, 'Estes, diante da igreja, testemunharam do teu amor; aos quais, tu agirás bem ao supri-los de modo digno [da vontade] de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 7, 'Pois foi por causa do Nome dele que partiram em jornada, sem nada aceitar dos gentios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 8, 'Portanto devemos acolher tais pessoas, para que sejamos cooperadores da verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 9, 'Eu tenho escrito aos da igreja; porém Diótrefes, que busca ser o comandante deles, não nos recebe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 10, 'Por isso, se eu vier, trarei à memória os seus feitos, falando ele contra nós com palavras maliciosas; e não satisfeito com isso, não recebe aos irmãos, proíbe aos que se dispõem a fazer, e os expulsa da igreja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 11, 'Amado, não imites o mal, mas sim o bem. Quem faz o bem é de Deus, mas quem faz o mal nunca viu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 12, 'Demétrio tem alcançado [bom] testemunho de todos, inclusive da própria verdade. Também nós damos testemunho, e vós sabeis que o nosso testemunho é verdadeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 13, 'Eu tinha muitas coisas para escrever, porém não quero escrever a ti [sobre elas] com tinta e pena;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 64, '3 João', '3Jo', 1, 14, 'mas espero te ver em breve, e falaremos face a face. Paz seja contigo. Os amigos [daqui] te saúdam. Saúda os amigos [daí] , cada um por nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 1, 'Judas, servo de Jesus Cristo, e irmão de Tiago, para aqueles [que foram] chamados, santificados por Deus Pai, e guardados por Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 2, 'Misericórdia a vós, e a paz e o amor [vos] sejam multiplicados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 3, 'Amados, procurando eu vos escrever com todo empenho sobre a [nossa] salvação comum, eu tive por necessário vos escrever e exortar a batalhar pela fé que de uma vez foi entregue aos santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 4, 'Porque alguns entraram disfarçadamente entre vós, que desde antes estavam escritos para a condenação; pessoas ímpias, que distorcem a graça de Deus em perversão, e negam ao único Soberano Deus e nosso Senhor Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 5, 'Mas eu quer vos lembrar, sabendo vós disto de uma vez por todas: que o Senhor, tendo liberto o povo para fora da terra do Egito, depois destruiu os que não creram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 6, 'E aos anjos que não guardaram sua origem, mas deixaram sua própria habitação, ele os reservou debaixo de grande escuridão em prisões eternas até o julgamento do grande dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 7, 'Assim como Sodoma e Gomorra, e as cidades circunvizinhas, que como aquelas, tendo cometido pecados sexuais, e seguido uma carne ilícita, foram postas como exemplo, recebendo a punição do fogo eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 8, 'Porém estes, também semelhantemente adormecidos, contaminam a carne, e rejeitam a soberania, e insultam as [coisas dignas de] glórias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 9, 'Mas Miguel, o arcanjo, quando ele discutia com o diabo, e disputava por causa do corpo de Moisés, não ousou contra [ele] pronunciar juízo de maldição, porém disse: “O Senhor te repreenda.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 10, 'Mas estes insultam tudo aquilo que não conhecem; e tudo o que eles entendem naturalmente, como animais irracionais, nisso eles se corrompem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 11, 'Ai deles; porque eles entraram pelo caminho de Caim, e se dispuseram ao engano de Balaão por interesse por [interesse de] lucro, e pereceram pela rebelião de Coré.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 12, 'Estes são manchas em vossas demonstrações de amor, participando dos banquetes convosco, apascentando a si mesmos sem temor; eles são nuvens sem água, levadas pelos ventos sem direção; são como árvores murchas, infrutíferas, duas vezes mortas e arrancadas pela raiz;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 13, 'Ondas furiosas do mar, que espumam suas próprias vergonhas; estrelas errantes, para as quais a escuridão das trevas está reservada eternamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 14, 'E Enoque, o sétimo depois de Adão, também profetizou sobre estes, dizendo: “Eis que o Senhor veio, com dezenas de milhares de seus santos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 15, 'para fazer julgamento contra todos, e reprovar a todos os seus ímpios, por todas as suas obras de irreverência, que impiamente cometeram, e por todas as duras [palavras] que os ímpios pecadores falaram contra ele.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 16, 'Estes são murmuradores, reclamadores, que andam segundo seus próprios maus desejos; e sua boca fala palavras de arrogância, mostrando admiração às pessoas para o [próprio] proveito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 17, 'Mas vós, amados, lembrai-vos das palavras que foram preditas pelos apóstolos de nosso Senhor Jesus Cristo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 18, 'Como eles vos diziam, que “no último tempo haveria escarnecedores, que andariam segundo seus próprios desejos ímpios.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 19, 'Estes são os que separam a si mesmos, mundanos, que não têm o Espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 20, 'Mas vós, amados, edificai a vós mesmos em vossa santíssima fé, orando no Espírito Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 21, 'Conservai a vós mesmos no amor de Deus, esperando a misericórdia de nosso Senhor Jesus Cristo para a vida eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 22, 'E tende misericórdia de alguns, usando de discernimento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 23, 'Mas a outros salvai em temor, arrancando [-os] do fogo, odiando até a roupa contaminada pela carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 24, 'E para aquele que é poderoso para vos guardar de tropeçar, e vos apresentar irrepreensíveis com alegria diante de sua glória;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 65, 'Judas', 'Jd', 1, 25, 'Ao único sábio Deus, nosso Salvador,[seja] a glória e majestade, poder e autoridade, agora, e para todo o sempre, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 1, 'Revelação de Jesus Cristo, a qual Deus lhe deu, para mostrar a seus servos as coisas que devem acontecer em breve; e as enviou por meio de seu anjo, e as informou ao seu servo João.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 2, 'O qual deu testemunho da palavra de Deus, e do testemunho de Jesus Cristo, e de tudo o que ele viu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 3, 'Bem-aventurado [é] aquele que lê, e [também] os que ouvem as palavras desta profecia, e guardam as coisas nela escritas; porque o tempo [está] próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 4, 'João, às sete igrejas que estão na Ásia. Graça e paz sejam convosco, [provenientes] daquele que é, e que era, e que virá; e dos sete Espíritos que estão diante do trono dele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 5, 'E de Jesus Cristo, que é a fiel testemunha, o primogênito dos mortos, e Chefe dos reis da terra; àquele que nos amou, e em seu sangue nos lavou de nossos pecados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 6, 'E nos fez reis e sacerdotes a Deus e seu Pai; a ele [seja] a glória e o poder para todo o sempre, Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 7, 'Eis que ele vem com as nuvens, e todo olho o verá, até mesmo aqueles que o perfuraram; e todas as tribos da terra lamentarão sobre ele. Sim! Amém!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 8, '“Eu sou o Alfa e o Ômega, o princípio e o fim”,diz o Senhor, que é, e que era, e que virá, o Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 9, 'Eu, João, (que também sou vosso irmão, e companheiro na aflição, e no Reino, e [na] paciência de Jesus Cristo), estava na ilha chamada Patmos, por causa da palavra de Deus, e por causa do testemunho de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 10, 'No dia do Senhor, eu fui [arrebatado] em espírito, e atrás de mim eu ouvi uma grande voz, como de trombeta,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 11, 'Dizendo: “Eu sou o Alfa e o Ômega, o primeiro e o último; e o que tu estás vendo, escreve em um livro, e envia às sete igrejas que estão na Ásia: a Éfeso, e a Esmirna, e a Pérgamo, e a Tiatira, e a Sardes, e a Filadélfia, e a Laodiceia”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 12, 'E eu me virei para ver a voz que tinha falado comigo; e ao me virar, vi sete castiçais de ouro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 13, 'E no meio dos sete castiçais, um semelhante a [o] Filho do homem, vestido até os pés de uma roupa comprida, e o tórax envolvido com um cinto de ouro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 14, 'E a cabeça e os cabelos dele eram brancos como a lã, brancos como a neve; e seus olhos como chama de fogo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 15, 'E os pés dele semelhantes a um metal valioso e reluzente, e ardentes como em fornalha; e a voz dele, como de muitas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 16, 'E tinha em sua [mão] direita sete estrelas; e de sua boca saía uma espada aguda de dois fios; e seu rosto como o sol brilhando em sua força.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 17, 'E quando eu o vi, cai aos pés dele como que morto; e ele pôs sua mão direita sobre mim, [e] me disse: “Não temas; eu sou o primeiro e o último;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 18, 'eu [sou] o que vivo, e fui morto; e eis que eu vivo para todo o sempre; Amém. E eu tenho as chaves do Xeol e da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 19, 'Escreve as coisas que tens visto, e as que são, e as que estão para acontecer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 1, 20, 'O mistério das sete estrelas, que viste em minha [mão] direita, e os sete castiçais de ouro: as sete estrelas são os anjos [ou mensageiros] das sete igrejas; e os sete castiçais que viste, são as sete igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 1, '“Escreve ao anjo da igreja de Éfeso: “Isto diz aquele que tem as sete estrelas em sua [mão] direita, que anda no meio dos sete castiçais de ouro:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 2, '“Eu conheço as tuas obras, e teu trabalho, e a tua paciência, e que tu não podes tolerar os maus; e provaste aos que se dizem ser apóstolos e não são; e reconheceste [que eles eram] mentirosos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 3, 'E suportaste [sofrimentos] , e tens paciência; e trabalhaste pelo meu nome, e não te cansaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 4, 'Mas eu tenho contra ti, que deixaste o teu primeiro amor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 5, 'Então lembra-te de onde tu caíste, e arrepende-te, e faze as primeiras obras; senão em breve eu virei a ti, e tirarei teu castiçal de seu lugar, se tu não te arrependeres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 6, 'Mas isto tu tens: que odeias as obras dos nicolaítas, as quais eu também odeio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 7, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: Ao que vencer, eu lhe darei de comer da árvore da vida, que está no meio do paraíso de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 8, '“E escreve ao anjo da igreja dos de Esmirna: “Isto diz o o primeiro e o último, que foi morto, e vive:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 9, '“Eu conheço tuas obras, e aflição, e pobreza (mas tu és rico) e a blasfêmia dos que dizem serem judeus, e não são, mas [na verdade] são sinagoga de Satanás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 10, 'Nada temas das coisas que virás a sofrer; eis que o diabo está para lançar [alguns] de vós em prisão, para que sejais tentados; e vós tereis aflição de dez dias. Sê fiel até a morte, e eu te darei a coroa da vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 11, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: o que vencer, não sofrerá o dano da segunda morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 12, '“E escreve ao anjo da igreja que está em Pérgamo: Isto diz aquele que tem a espada aguda de dois fios:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 13, 'Eu conheço tuas obras, e onde habitas, [que é] onde [está] o trono de Satanás; e tu reténs meu nome, e não negaste minha fé, [até] mesmo nos dias em que Antipas, que [era] minha fiel testemunha, o qual foi morto entre vós, onde Satanás habita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 14, 'Mas eu tenho [algumas] poucas coisas contra ti: que tu tens lá aos que retêm a doutrina de Balaão, o qual ensinava a Balaque a colocarmeios de tropeço diante dos filhos de Israel, para que comessem dos sacrifícios aos ídolos, e cometessem pecados sexuais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 15, 'Assim, também tu tens alguns que guardam a doutrina dos nicolaítas, a qual eu odeio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 16, 'Arrepende-te; senão, em breve virei a ti, e batalharei contra eles com a espada de minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 17, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas: Ao que vencer, eu lhe darei de comer do maná escondido, e lhe darei uma pedrinha branca, e na pedrinha um novo nome escrito, o qual ninguém conhece, a não ser aquele que [o] recebe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 18, '“E escreve ao anjo da igreja que [está] em Tiatira: “Isto diz o Filho de Deus, que tem seus olhos como chama de fogo, e seus pés semelhantes a um valioso metal reluzente:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 19, '“Eu conheço tuas obras, e amor, e serviço, e fé, e tua paciência, e tuas obras, e [que] as últimas são mais que as primeiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 20, 'Mas eu tenho [algumas] poucas coisas contra ti: que tu deixas a mulher Jezabel, que se diz profetiza, ensinar e enganar meus servos, para que façam pecados sexuais, e comam dos sacrifícios aos ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 21, 'E eu dei a ela tempo para que se arrependesse de seu pecado sexual; mas ela não se arrependeu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 22, 'Eis que eu a lanço a [uma] cama, e aos que cometem adultério com ela, em grande aflição, se não se arrependerem de suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 23, 'E ao filhos deles eu os matarei de morte; e todas as igrejas saberão que eu sou aquele que investigo os rins e os corações; e a cada um de vós eu darei segundo vossas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 24, 'Mas eu digo a vós, e aos outros que estão em Tiatira, a todos quantos não tem esta dourina, e não conheceram as profundezas de Satanás (como dizem); eu não porei outra carga sobre vós;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 25, 'Mas o que vós tendes, retende até que eu venha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 26, 'E ao que vencer, e guardar minhas obras até o fim, eu lhe darei autoridade sobre as nações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 27, 'E as dominará com vara de ferro; como vasos de oleiro serão quebradas em pedaços; assim como eu também recebi do meu Pai;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 28, 'E eu lhe darei a estrela da manhã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 2, 29, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 1, '“E escreve ao anjo da igreja que [está] em Sardes: “Isto diz aquele que tem os sete espíritos de Deus, e as sete estrelas: “Eu conheço tuas obras; que tu tens nome de que vives, e estás morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 2, 'Sê vigilante, e firma o resto que está a ponto de morrer; porque eu não achei tuas obras completas diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 3, 'Então lembra-te do que tu tens recebido e ouvido, e guarda, e arrepende-te. Portanto, se tu não vigiares, eu virei sobre ti como ladrão, e tu não saberás a que hora eu virei sobre ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 4, 'Mas também em Sardo tu tens [alguns] poucos nomes, [ou seja, pessoas] que não contaminaram suas roupas, e andarão comigo em [roupas] brancas, porque são dignos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 5, 'O que vencer, este será vestido de roupas brancas; e seu nome em maneira nenhuma riscarei do livro da vida; e eu declararei seu nome diante do meu Pai, e diante de seus anjos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 6, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 7, '“E escreve ao anjo da igreja que [está] em Filadélfia: “Isto diz o Santo, o Verdadeiro, que tem a chave de Davi; que abre e ninguém fecha; [que] fecha e ninguém abre;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 8, '“Eu conheço as tuas obras; eis que eu te dei diante de ti uma porta aberta, e ninguém a pode fechar; porque tu tens pouca força, e guardaste minha palavra, e não negaste o meu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 9, 'Eis que eu entrego [alguns] da sinagoga de Satanás, dos que dizem ser judeus, e não são, mas mentem; eis que eu farei com que venham, e fiquem prostrados diante dos teus pés, e saibam que eu te amo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 10, 'Porque tu guardaste a palavra da minha paciência, também eu te guardarei da hora da provação que está para vir sobre todo o mundo, para testar aos que habitam sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 11, 'Eis que eu venho em breve; guarda o que tu tens, para que ninguém tome tua coroa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 12, 'Ao que vencer, eu o farei coluna no templo do meu Deus; e dele nunca mais sairá; e sobre ele escreverei o nome do meu Deus, e o nome da cidade do meu Deus, Nova Jerusalém, que desce do céu do meu Deus, e [também] meu novo nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 13, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 14, '“E escreve ao anjo da igreja dos laodicenses: “Isto diz o Amém, a testemunha fiel e verdadeira, o principal da criação de Deus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 15, '“Eu conheço as tuas obras, que tu nem és frio, nem quente; melhor seria que tu fosses frio ou quente!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 16, 'Portanto porque tu és morno, e nem frio nem quente, eu te vomitarei da minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 17, 'Porque tu dizes: Eu sou rico, e tenho me enriquecido, e de nada tenho falta; E não sabes que estás miserável, coitado, pobre, cego e nu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 18, 'Eu te aconselho a comprar de mim ouro provado do fogo, para que te enriqueças; e roupas brancas, para que te vistas; e a vergonha de tua nudez não apareça; e unge teus olhos com colírio, para que vejas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 19, 'Eu repreendo e castigo a todos quantos eu amo; portanto sê zeloso, e te arrepende.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 20, 'Eis que eu estou à porta, e bato; se alguém ouvir a minha voz, e abrir a porta, entrarei até ele, e cearei com ele, e ele comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 21, 'Ao que vencer, eu lhe concederei que se sente comigo em meu trono; assim como eu também venci, e me sentei com meu Pai no trono dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 3, 22, 'Quem tem ouvidos, ouça o que o Espírito diz às igrejas.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 1, 'Depois destas coisas eu olhei, e eis que uma porta estava aberta no céu; e a primeira voz que eu ouvi, como uma trombeta ao falar comigo, disse: “Sobe aqui, e eu te mostrarei as coisas que devem acontecer depois destas.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 2, 'E logo eu fui [arrebatado] em espírito; e eis que um trono estava posto no céu, e [alguém] sentado sobre o trono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 3, 'E o que estava sentado era de aparência semelhante à pedra jaspe e sárdio; e o arco colorido celeste estava ao redor do trono, de aparência semelhante à esmeralda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 4, 'E ao redor do trono [havia] vinte e quatro tronos; e vi sobre os tronos vinte e quatro anciãos vestidos de roupas brancas; e sobre as cabeças deles tinham coroas de ouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 5, 'E do trono saíam relâmpagos, e trovões, e vozes; e sete lâmpadas de fogo ardiam diante do trono, as quais são os sete espíritos de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 6, 'E diante do trono [havia] um mar de vidro, semelhante ao cristal, e no meio do trono, e ao redor do trono, quatro animais cheios de olhos, em frente e atrás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 7, 'E o primeiro animal [era] semelhante a um leão, e o segundo animal semelhante a um bezerro, e o terceiro animal tinha o rosto como de homem, e o quarto animal [era] como uma águia voando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 8, 'E os quatro animais tinham cada um em si seis asas ao redor, e por dentro [eram] cheios de olhos; e não tem repouso de dia nem de noite, dizendo: “Santo, Santo, Santo [é] o Senhor Deus, o Todo-Poderoso, que era, e que é, e que virá.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 9, 'E quando os animais dão glória, honra, e agradecimento ao que estava sentado sobre o trono, ao que vive para todo o sempre;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 10, '[Então] os vinte e quatro anciãos se prostram diante do que estava sentado sobre o trono, e adoram ao que vive para todo o sempre, e lançam suas coroas diante do trono, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 4, 11, '“Digno és tu, Senhor, de receberes glória, honra e poder; porque tu criaste todas as coisas, e por causa da tua vontade elas são e foram criadas!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 1, 'E eu vi na [mão] direita do que estava sentado sobre o trono um livro escrito por dentro e por fora, selado com sete selos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 2, 'E vi um forte anjo, proclamando em alta voz: “Quem é digno de abrir o livro, e soltar seus selos?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 3, 'E ninguém no céu, nem na terra podia abrir o livro, nem olhar [para] ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 4, 'E eu chorei muito, porque ninguém foi achado digno de abrir o livro, nem de o ler, nem olhar [para] ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 5, 'E um dos anciãos me disse: “Não chores; eis que o Leão da tribo de Judá, a raiz de Davi, venceu, para abrir o livro e soltar seus sete selos.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 6, 'E eu olhei, e eis que no meio do trono, e dos quatro animais, e no meio dos anciãos, um Cordeiro que estava como se tivesse sido morto, e tinha sete chifres, e sete olhos, que são os sete espíritos de Deus enviados para toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 7, 'E ele veio, e tomou o livro da [mão] direita daquele que estava sentado sobre o trono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 8, 'E quando ele tomou o livro, os quatro animais, e os vinte e quatro anciãos se prostraram diante do Cordeiro, tendo cada um harpas, e recipientes de ouro cheios de perfumes, que são as orações dos santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 9, 'E eles cantavam um novo cântico, dizendo: “Digno és tu de tomar o livro, e abrir seus selos; porque foste morto, e com o teu sangue para Deus nos compraste , de toda tribo, língua, povo, e nação;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 10, 'e para nosso Deus tu nos fizeste reis e sacerdotes; e nós reinaremos sobre a terra.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 11, 'E eu olhei, e ouvi uma voz de muitos anjos ao redor do trono, e dos animais, e dos anciãos; e o número deles era de centenas de milhões, e milhares de milhares;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 12, 'que diziam em alta voz: “Digno é o Cordeiro que foi morto, de receber poder, riquezas, sabedoria, força, honra, glória, e louvor!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 13, 'E eu ouvi toda criatura que está no céu, e na terra, e abaixo da terra, e no mar, e todas as coisas que nelas há, dizendo: “Ao que está sentado sobre o trono, e ao Cordeiro, seja o louvor, a honra, a glória, e o poder, para todo o sempre!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 5, 14, 'E os quatro animais diziam: “Amém!” E os vinte e quatro anciãos se prostraram e adoraram ao que vive para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 1, 'E eu vi quando o Coreiro abriu um dos selos; e ouvi um dos quatro animais dizendo [com] voz como de trovão: “Vem, e vê.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 2, 'E eu olhei, e eis um cavalo branco; e o que estava sentado sobre ele tinha um arco; e uma coroa lhe foi dada, e ele saiu [como] conquistador, e para que conquistasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 3, 'E quando ele abriu o segundo selo, eu ouvi o segundo animal dizendo: “Vem, e vê.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 4, 'E saiu outro cavalo vermelho; e ao que estava sentado sobre ele foi concedido que tirasse a paz da terra, e que uns aos outros se matassem; e uma grande espada lhe foi dada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 5, 'E quando ele abriu o terceiro celo, eu ouvi o terceiro animal dizer: “Vem, e vê.” E olhei, e eis um cavalo preto, e o que estava sentado sobre ele tinha uma balança na sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 6, 'E ouvi uma voz no meio dos quatro animais, dizendo: “Uma medida de trigo por um dinheiro, e três medidas de cevada por um dinheiro; e não danifiques o azeite e o vinho.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 7, 'E quando ele abriu o quarto selo, eu ouvi a voz do quarto animal dizendo: “Vem, e vê.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 8, 'E eu olhei, e eis um cavalo amarelo, e o que estava sentado sobre ele, seu nome [era] Morte; e o Xeol o seguia. E foi-lhes dada autoridade para matar a quarta [parte] da terra, com espada, com fome, com morte [por doença] , e com os animais ferozes da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 9, 'E quando ele abriu o quinto selo, eu vi debaixo do altar as almas dos que foram mortos por causa da palavra de Deus, e por causa do testemunho que tinham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 10, 'E clamavam com grande voz, dizendo: “Até quando, Santo e Verdadeiro Soberano, não julgas e vingas nosso sangue daqueles que habitam sobre a terra?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 11, 'E foram dados a cada um [deles] compridas roupas brancas; e foi-lhes dito que repousassem ainda um pouco de tempo, até que se completassem os seus companheiros de serviço e seus irmãos, que [ainda] viriam a ser mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 12, 'E eu vi quando ele abriu o sexto selo, e eis que houve um grande tremor de terra; e o sol se tornou preto como um saco feito de pelos de animais, e a lua se tornou como sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 13, 'E as estrelas do céu caíram sobre a terra como a figueira lança de si seus figos verdes, abalada por um grande vento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 14, 'E o céu se removeu como um rolo de livro que se enrola; e todos os montes e ilhas se moveram de seus lugares.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 15, 'E os reis da terra, e os grandes, e os rigos, e os comandantes, e os poderosos, e todo escravo, e todo livre se esconderam nas cavernas e nas rochas das montanhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 16, 'E diziam aos montes, e às rochas: “Caí sobre nós, e escondei-nos do rosto daquele que está sentado sobre o trono, e da ira do Cordeiro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 6, 17, 'Porque chegou o dia da sua grande ira; e quem poderá ficar de pé?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 1, 'E depois destas coisas eu vi quatro anjos que estavam sobre os quatro cantos da terra, retendo os quatro ventos da terra, para que nenhum vento soprasse sobre a terra, nem sobre o mar, nem sobre árvore alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 2, 'E eu vi outro anjo subir do lado onde o sol nasce, que tinha o selo do Deus vivente, e clamou com grande voz aos quatro anjos, aos quais tinha sido dado [poder] para danificar a terra e o mar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 3, 'Dizendo: “Não danifiques a terra, nem o mar, nem as árvores, até que tenhamos selado aos servos do nosso Deus nas suas testas.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 4, 'E ouvi o número dos que foram selados; e cento e quarenta e quatro mil foram selados de todas as tribos dos filhos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 5, 'Da tribo de Judá, doze mil foram selados; da tribo de Rúben, doze mil foram selados; da tribo de Gade, doze mil foram selados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 6, 'da tribo de Aser, doze mil foram selados; da tribo de Naftali, doze mil foram selados; da tribo de Manassés, doze mil foram selados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 7, 'da tribo de Simeão, doze mil foram selados; da tribo de Levi, doze mil foram selados; da tribo de Issacar, doze mil foram selados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 8, 'da tribo de Zebulom, doze mil foram selados; da tribo de José, doze mil foram selados; da tribo de Benjamim, doze mil foram selados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 9, 'Depois destas coisas eu olhei, e eis uma grande multidão, a qual ninguém podia contar, de todas as nações, e tribos, e povos, e línguas, que estavam diante do trono e diante do Cordeiro, vestidos de roupas brancas, e [com ramos] de palmas nas suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 10, 'E clamavam com grande voz, dizendo: “A salvação [pertence] ao nosso Deus, que está sentado sobre o trono, e ao Cordeiro!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 11, 'E todos os anjos estavam ao redor do trono, e dos anciãos, e dos quatro animais; e se prostraram sobre seus rostos diante do trono, e adoraram a Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 12, 'Dizendo: “Amém! [Sejam] louvor, glória, sabedoria, agradecimento, honra, poder, e força a nosso Deus, para todo o sempre, Amém!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 13, 'E um dos anciãos respondeu, dizendo-me: “Estes que estão vestidos de roupas compridas brancas, quem são? E de onde eles vieram?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 14, 'E eu lhe disse: “Senhor, tu sabes.” E ele me disse: “Estes são os que vieram da grande tribulação; e lavaram suas roupas compridas e as branquearam no sangue do Cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 15, 'Por isso eles estão diante do trono de Deus, e servem a ele dia e noite no seu templo; e aquele que está sentado sobre o trono armará sua tenda e habitará com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 16, 'Eles não mais terão fome, nem mais terão sede; nem o sol, nem calor algum cairá sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 7, 17, 'Porque o Cordeiro, que está no meio do trono, os apascentará, e os guiará até fontes vivas de águas; e Deus limpará toda lágrima dos seus olhos.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 1, 'E quando ele abriu o sétimo selo, houve silêncio no céu por cerca de meia hora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 2, 'E eu vi os sete anjos, que estavam diante de Deus; e foram-lhes dadas sete trombetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 3, 'E veio outro anjo, e se ficou junto ao altar, tendo um incensário de ouro; e muitos incensos lhe foram dados, para que oferecesse com as orações de todos os santos sobre o altar de ouro que está diante do trono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 4, 'E a fumaça dos incensos com as orações dos santos subiu desde a mão do anjo até diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 5, 'E o anjo tomou o incensário, e o encheu do fogo do altar, e o lançou sobre a terra; e houve vozes, trovões, relâmpagos e terremotos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 6, 'E os sete anjos, que tinham as sete trombetas, se prepararam para [as] tocarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 7, 'E o primeiro anjo tocou sua trombeta; e houve saraiva e fogo misturado com sangue; e foram lançados sobre a terra; e a terça parte das árvores se queimou, e toda a erva verde foi queimada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 8, 'E o segundo anjo tocou sua trombeta; e como um grande monte ardendo em fogo foi lançado ao mar; e a terça [parte] do mar se tornou sangue;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 9, 'E morreu a terça [parte] das criaturas que tinham vida no mar; e a terça [parte] das embarcações foi destruída.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 10, 'E o terceiro anjo tocou sua trombeta; e uma grande estrela caiu do céu ardendo como uma tocha; e ela caiu na terça [parte] dos rios, e nas fontes de águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 11, 'E o nome da estrela se chama Absinto; e a terça [parte] das águas se tornou absinto; e muitos homens morreram por causa das águas, porque elas se tornaram amargas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 12, 'E o quarto anjo tocou sua trombeta; e a terça [parte] do sol foi ferida, e [também] a terça [parte] da lua, e a terça [parte] das estrelas; para que a terça [parte] deles se escurecesse, e o dia não clareasse pela sua terça [parte] ; e [se tornasse] semelhante à noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 8, 13, 'E olhei, e ouvi um anjo que estava voando pelo meio do céu, dizendo em alta voz: “Ai, ai, ai dos que habitam sobre a terra por causa das demais vozes das trombetas dos três anjos que ainda vão tocar!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 1, 'E o quinto anjo tocou sua trombeta; e eu vi uma estrela que caiu do céu sobre a terra; e foi-lhe dada a chave do poço do abismo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 2, 'E o poço do abismo foi aberto; e subiu fumaça do poço, como a fumaça de uma grande fornalha; e o sol e o ar se escureceram [por causa] da fumaça do poço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 3, 'E da fumaça saíram gafanhotos sobre a terra; e foi dado a eles poder como o poder que os escorpiões da terra têm.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 4, 'E foi-lhes dito que não fizessem dano à erva da terra, nem a nenhuma [planta] verde, nem a nenhuma árvore; mas sim somente aos homens que não têm o sinal de Deus em suas testas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 5, 'E foi-lhes concedido que não os matassem, mas sim que os atormentassem por cinco meses; e o tormento deles era semelhante ao tormento do escorpião, quando fere ao homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 6, 'E naqueles dias os homens buscarão a morte, e não a acharão; e desejarão morrer, e a morte fugirá deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 7, 'E a aparência dos gafanhotos [era] semelhante à de cavalos preparados para a batalha; e sobre as cabeças deles havia como coroas, semelhantes ao ouro; e seus rostos eram como rostos de homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 8, 'E tinham cabelos como cabelos de mulheres; e seus dentes eram como os de leões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 9, 'E tinham couraças como couraças de ferro; e o ruído de suas asas era como o ruído de carruagens de muitos cavalos correndo para a batalha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 10, 'E tinham caudas semelhantes às de escorpiões; e ferrões em suas caudas; e seu poder era de por cinco meses causarem dano aos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 11, 'E tinham como rei sobre eles ao anjo do abismo; o nome dele em hebraico [é] “Abadom”, e em grego tem por nome “Apoliom”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 12, 'Um ai [já] passou; eis que depois disto ainda vêm dois ais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 13, 'E o sexto anjo tocou sua trombeta; e eu ouvi uma voz dos quatro chifres do altar de ouro, que estava diante de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 14, 'A qual dizia ao sexto anjo, que tinha a trombeta: “Solta os quatro anjos que estão presos junto ao grande rio Eufrates.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 15, 'E foram soltos os quatro anjos, que tinham sido preparados para a hora, dia, mês e ano, para matarem a terça [parte] da humanidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 16, 'E o número dos exércitos de cavaleiros era duzentos milhões; e eu ouvi o número deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 17, 'E assim eu vi os cavalos n [esta] visão; e os que cavalgavam sobre eles tinham couraças de fogo, de jacinto e de enxofre; e as cabeças dos cavalos [eram] como cabeças de leões; e de suas bocas saía fogo, fumaça e enxofre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 18, 'Por estes três a terça [parte] dos homens foi morta, pela fogo, pela fumaça e pelo enxofre que saía de suas bocas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 19, 'Porque o poder deles está em sua boca, e em suas caudas; porque suas caudas [são] semelhantes a serpentes tendo cabeças, e com elas causam dano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 20, 'E o resto da humanidade, que não foi morta por estas pragas, não se arrependeu das obras de suas mãos, para não adorar os demônios, e ídolos de ouro, de prata, de bronze, de pedra e de madeira, que não podem ver, nem ouvir, nem andar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 9, 21, 'E não se arrependeu de seus homicídios, nem de suas feitiçarias, nem de seu pecado sexual, nem de seus roubos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 1, 'E eu vi outro forte anjo descendo do céu, vestido com uma nuvem; e por cima de [sua] cabeça [estava] o arco colorido celeste; e o rosto dele [era] como o sol, e os pés dele como coluna de fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 2, 'E na mão dele tinha um livrinho aberto; e pôs seu pé direito sobre o mar, e o esquerdo sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 3, 'E clamou em alta voz, como quando o leão ruge; e quando ele clamou, os sete trovões falaram suas vozes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 4, 'E quando os sete trovões falaram suas vozes, eu estava a pondo de escrevê [-las] ; mas eu ouvi uma voz do céu me dizer: “Sela as coisas que os sete trovões falaram, e não as escrevas.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 5, 'E o anjo que eu vi estar sobre o mar e sobre a terra levantou sua mão ao céu,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 6, 'E jurou por aquele que vive para todo o sempre, o qual criou o céu e as coisas que nele há, e a terra e as coisas que nela há, e o mar e as coisas que nele há, que não haverá mais tempo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 7, 'Mas [que] nos dias da voz do sétimo anjo, quando sua trombeta estiver a ponto de tocar, o mistério de Deus se cumprirá, assim como ele bem anunciou aos seus servos e profetas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 8, 'E a voz que eu tinha ouvido do céu voltou a falar comigo, e disse: “Vai, [e] toma o livrinho aberto da mão do anjo que está sobre o mar e sobre a terra.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 9, 'E eu fui até o anjo, dizendo-lhe: “Dá-me o livrinho.” E ele me disse: “Toma-o, e come-o; e fará amargo o teu ventre, mas em tua boca será doce como mel.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 10, 'E eu tomei o livrinho da mão do anjo, e comi; e ele era em minha boca doce como o mel; mas quando eu o comi, meu ventre ficou amargo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 10, 11, 'E ele me disse: “É necessário que profetizes outra vez a muitos povos, nações, línguas e reis.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 1, 'E foi-me dada uma cana semelhante a uma vara [de medir] ; e o anjo ficou [de pé] , dizendo: “Levanta-te, e mede o templo de Deus, e o altar, e os que nele adoram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 2, 'Mas deixa fora ao pátio, que [está] fora do templo, e não o meças; porque ele foi dado às nações; e pisarão a santa cidade por quarenta e dois meses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 3, 'E eu darei [autoridade] às minhas duas testemunhas, e elas profetizarão por mil duzentos e sessenta dias, vestidas de sacos.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 4, 'Estas são as duas oliveiras, e os dois castiçais, que estão diante do Deus da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 5, 'E se alguém quiser lhes maltratar, fogo sai da sua boca, e devora aos inimigos delas; e se alguém quiser lhes maltratar, é necessário que assim seja morto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 6, 'Estas têm autoridade para fechar o céu, para que não chova nos dias da sua profecia; e têm poder sobre as águas para as transformar em sangue, e para ferir a terra com toda praga, tantas vezes quantas quiserem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 7, 'E quando elas terminarem seu testemunho, a besta, que sobe do abismo, fará guerra contra elas, e as vencerá, e as matará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 8, 'E os cadáveres delas [jazerão] na praça da grande cidade, que espiritualmente se chama Sodoma e Egito, onde nosso Senhor também foi crucificado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 9, 'E os dos povos, tribos, línguas e nações verão os cadáveres delas por três dias e meio, e não permitirão que os cadáveres delas sejam postos em sepulcros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 10, 'E os que habitam sobre a terra se alegrarão sobre elas, e ficarão contentes, e enviarão presentes uns aos outros, porque estes dois profetas atormentarão aos que habitam sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 11, 'E depois [daqueles] três dias e meio, entrou nelas o espírito de vida de Deus, e se puseram sobre seus pés, e caiu grande temor sobre os que as viram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 12, 'E elas ouviram uma grande voz do céu lhes dizendo: “Subi aqui!” E elas subiram ao céu em uma nuvem; e seus inimigos as viram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 13, 'E naquela [mesma] hora houve um grande terremoto, e a décima [parte] da cidade caiu, e no terremoto foram mortos sete mil nomes humanos; e os restantes ficaram muito atemorizados, e deram glória ao Deus do céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 14, 'O segundo ai [já] passou; eis que o terceiro ai logo vem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 15, 'E o sétimo anjo tocou a trombeta, e houve grandes vozes no céu, dizendo: “Os reinos do mundo se tornaram do nosso Senhor, e do seu Cristo, e ele reinará para todo o sempre.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 16, 'E os vinte e quatro anciãos, que estão sentados diante de Deus em seus tronos, prostraram-se sobre seus rostos, e adoraram a Deus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 17, 'dizendo: “Graças te damos, Senhor Deus, o Todo-Poderoso, o que é, e que era, e que virá; porque tomaste o teu grande poder, e tens reinado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 18, 'E as nações se iraram, porém veio a tua ira, e o tempo dos mortos, para serem julgados, e para tu dares a recompensa aos teus servos, os profetas, e aos santos, e aos que temem o teu nome, a pequenos e a grandes; e para destruir os que destroem a terra.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 11, 19, 'E o templo de Deus se abriu no céu, e a arca de seu pacto foi vista no seu templo; e houve relâmpagos, vozes, trovões, terremotos, e grande queda de granizo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 1, 'E um grande sinal foi visto no céu: uma mulher vestida do sol, e a lua debaixo dos pés dela, e sobre sua cabeça uma coroa de doze estrelas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 2, 'E ela estava grávida, gritando, tendo dores de parto, e sendo atormentada pelo trabalho de parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 3, 'E foi visto outro sinal no céu; e eis que [era] um grande dragão vermelho, que tinha sete cabeças e dez chifres, e sobre suas cabeças sete coroas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 4, 'E sua cauda levava [após si] a terça [parte] das estrelas do céu, e as lançou sobre a terra; e o dragão ficou parado diante da mulher, que estava a ponto de gerar [filho] ; para que, quando ela desse à luz, [o dragão] devorasse o filho dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 5, 'E ela gerou um filho macho, que com vara de ferro ia dominar todas as nações; e o filho dela foi arrebatado para Deus e para o seu trono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 6, 'E a mulher fugiu para o deserto, onde ela tinha lugar preparado por Deus, para que ali a alimentassem por mil duzentos e sessenta dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 7, 'E houve batalha no céu: Miguel e seus anjos batalhavam contra o dragão; e batalhava [também contra eles] o dragão e seus anjos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 8, 'Mas eles não prevaleceram, nem mais o lugar deles foi achado nos céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 9, 'E foi lançado o grande dragão, a serpente antiga, chamada o diabo e Satanás, que engana a todo o mundo; ele foi lançado na terra, e seus anjos foram lançados com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 10, 'E eu ouvi uma grande voz no céu, dizendo: “Agora veio a salvação, e a força, e o reino de nosso Deus, e o poder de seu Cristo; porque [já] foi lançado abaixo o acusador dos nossos irmãos, o qual os acusava diante de nosso Deus dia e noite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 11, 'E eles o venceram pelo sangue do Cordeiro, e pela palavra do testemunho deles; e eles não amaram suas vidas até a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 12, 'Por isso alegrai-vos, ó céus, e os que nele habitais! Ai dos que habitam na terra, e no mar! Porque o diabo desceu até vos, tendo grande ira, sabendo que ele tem pouco tempo.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 13, 'E quando o dragão viu que havia sido lançado na terra, ele perseguiu a mulher que tinha dado à luz o menino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 14, 'E foram dadas à mulher duas asas de grande água, para que voasse ao deserto, ao lugar dela, onde ali é alimentada por um tempo, e tempos, e a metade de um tempo, [longe] da face da serpente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 15, 'E a serpente lançou de sua boca água como [de] um rio, atrás da mulher, para fazer [com que] esta [mulher] seja levada pela correnteza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 16, 'E a terra ajudou a mulher, e a terra abriu a sua boca, e engoliu o rio que o dragão havia lançado de sua boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 12, 17, 'E o dragão se irou contra a mulher, e saiu para fazer guerra contra os restantes da descendência dela, os que guardam os mandamentos de Deus e têm o testemunho de Jesus Cristo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 1, 'E eu fiquei parado sobre a areia do mar. E vi subir do mar uma besta, que tinha sete cabeças e dez chifres, e sobre seus chifres dez diademas; e sobre suas cabeças um nome de blasfêmia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 2, 'E a besta que eu vi era semelhante a um leopardo, e seus pés como de urso, e sua boca como boca de leão; e o dragão lhe deu seu poder, e seu trono, e grande autoridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 3, 'E eu vi uma de suas cabeças como ferida de morte, e sua ferida mortal foi curada; e toda a terra se admirou e seguiu a besta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 4, 'E adoraram ao dragão, ao qual tinha dado poder à besta; e [também] adoraram à besta, dizendo: “Quem [é] semelhante à besta? Quem pode batalhar contra ela?”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 5, 'E foi-lhe dada um boca que falava grandes coisas e blasfêmias; também foi-lhe dada autoridade para agir por quarenta e dois meses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 6, 'E ela abriu sua boca em blasfêmia contra Deus, para blasfemar do nome dele, e do tabernáculo dele, e daqueles que habitam no céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 7, 'E foi-lhe concedido fazer guerra aos santos, e os vencer; e foi-lhe dada autoridade sobre toda tribo, língua, e nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 8, 'E todos os que habitam sobre a terra a adorarão, o nomes dos quais não estão escritos no livro da vida do Cordeiro, que foi morto desde a fundação do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 9, 'Se alguém tem ouvido, ouça:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 10, '“Se alguém leva em cativeiro, em cativeiro irá; se alguém matar à espada, é necessário que à espada ele seja morto.” Aqui está a paciência e a fé dos santos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 11, 'E eu vi outra besta subindo da terra, e tinha dois chifres semelhantes aos de um cordeiro; e ela falava como um dragão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 12, 'E ela exercita todo o poder da primeira besta em sua presença; e faz que a terra e os que nela habitam, adorem à primeira besta, cuja ferida mortal havia sido curada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 13, 'E ela faz grandes sinais, de maneira que faz até fogo descer do céu à terra, diante dos seres humanos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 14, 'E engana aos que habitam na terra por meio de sinais, que lhe foram concedidos fazer na presença da besta; dizendo aos que habitam na terra para fazerem uma imagem para a besta que tinha [recebido] a ferida da espada, e sobreviveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 15, 'E foi-lhe concedido dar espírito à imagem da besta, para que a imagem da besta também falasse, e fizesse que todos os que não adorassem à imagem da besta fossem mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 16, 'E fez com que todos, os pequenos e os grandes, os ricos e os pobres, os livres e os escravos, fosse lhes dada uma marca sobre sua mão direita ou sobre suas testas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 17, 'E que ninguém possa comprar ou vender, a não ser aquele que tenha a marca ou o nome da besta, ou o número do nome dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 13, 18, 'Aqui está a sabedoria: aquele que tem entendimento, calcule o número da besta, porque é número humano; e seu número é seiscentos e sessenta e seis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 1, 'E eu olhei, e eis que o Cordeiro estava de pé sobre o monte Sião, e com ele cento e quarenta e quatro mil, tendo o nome do Pai dele escrito em suas testas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 2, 'E eu ouvi uma voz do céu como voz de muitas águas, e como voz de um grande trovão; e ouvi uma voz de tocadores de harpas, que tocavam com suas harpas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 3, 'E cantavam um cântico novo diante do trono, e diante dos quatro animais, e dos anciãos; e ninguém podia aprender aquele cântico, a não ser os cento e quarenta e quatro mil que tinham sido comprados da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 4, 'Estes são os que não se contaminaram com mulheres, porque são virgens; estes são os que seguem ao Cordeiro onde quer que ele vá; estes foram comprados dentre os homens, [sendo] primícias para Deus e para o Cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 5, 'E não foi encontrado engano na boca deles, porque eles são irrepreensíveis diante do trono de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 6, 'E eu vi outro anjo voando tendo o evangelho eterno, para proclamá-lo aos que habitam sobre a terra, e a toda nação, tribo, língua e povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 7, 'dizendo em alta voz: “Temei a Deus, e dai glória a ele; porque chegou a hora do seu julgamento; e adorai àquele que fez o céu, a terra, o mar e as fontes de águas.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 8, 'E seguiu outro anjo, dizendo: “Ela caiu! Caiu a Babilônia, a grande cidade, porque ela deu de beber a todas as nações do vinho da ira de seu pecado sexual.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 9, 'E o terceiro anjo os seguiu, dizendo em alta voz: “Se alguém adora a besta e a sua imagem, e recebe a marca [dela] sobre sua testa, ou sobre sua mão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 10, 'também o tal beberá do vinho da ira de Deus, que foi posto sem mistura no cálice de sua ira; e será atormentado com fogo e enxofre, diante dos santos anjos e diante do Cordeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 11, 'E a fumaça do tormento deles sobe para todo o sempre; e não têm descanso de dia nem de noite os que adoram a besta e a sua imagem, e se alguém recebe a marca de seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 12, 'Aqui está a paciência dos santos; aqui [estão] os que guardam os mandamentos de Deus e a fé em Jesus.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 13, 'E eu ouvi uma voz do céu, que me dizia: Escreve: “Benditos são os mortos que morrem no Senhor a partir de agora; sim, diz o Espírito, para que se descansem de seus trabalhos; e suas obras os seguem.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 14, 'E eu olhei, e eis uma nuvem branca, e um semelhante a um filho do homem, sentado sobre a nuvem; tendo sobre sua cabeça uma coroa de ouro, e em sua mão uma foice afiada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 15, 'E outro anjo saiu do templo, clamando em alta voz ao que estava sentado sobre a nuvem: “Envia a tua foice, e ceifa; pois chegou a ti a hora de ceifar, porque a plantação da terra [já] está madura.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 16, 'E aquele que está sentado sobre a nuvem lançou sua foice na terra, e a terra foi ceifada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 17, 'E outro anjo saiu do templo que está no céu, o qual também tinha uma foice afiada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 18, 'E outro anjo, que tinha poder sobre o fogo, saiu do altar; e ele clamou em alta voz ao que tinha a foice afiada, dizendo: “Envia a tua foice afiada, e recolhe os cachos da vinha da terra; porque suas uvas [já] estão maduras.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 19, 'E o anjo lançou sua foice à terra, e recolheu [as uvas] da vinha da terra, e [as] lançou na prensa da grande ira de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 14, 20, 'E a prensa foi pisada fora da cidade, e saiu sangue da prensa até os freios dos cavalos, por mil e seiscentos estádios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 15, 1, 'E eu vi outro grande e admirável sinal no céu: sete anjos, que tinham as sete últimas pragas; porque nelas a ira de Deus se torna completa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 15, 2, 'E eu vi como um mar de vidro misturado como fogo; e aos que venceram a besta, a sua imagem, e sua marca, [e] o número de seu nome, os quais estavam de pé junto ao mar de vidro, e tinham harpas de Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 15, 3, 'E cantavam o cântico de Moisés, o servo de Deus, e o cântico do Cordeiro, dizendo: “Grandes e maravilhosas [são] as tuas obras, [ó] Senhor Deus Todo-Poderoso! Teus caminhos são justos e verdadeiros, [ó] Rei dos santos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 15, 4, 'Quem não te temeria, [ó] Senhor, e não glorificaria o teu nome? Porque só tu és santo; porque todas as nações virão, e adorarão diante de ti, porque os teus juízos foram manifestos!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 15, 5, 'E depois disto eu olhei, e eis que o templo do tabernáculo do testemunho foi aberto no céu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 15, 6, 'E os sete anjos, que tinham as sete pragas, saíram do templo, vestidos de linho puro e brilhante, e cingidos com cintos de ouro ao redor dos peitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 15, 7, 'E um dos quatro animais deu aos sete anjos sete taças de ouro, cheias da ira de Deus, aquele que vive para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 15, 8, 'E o templo se encheu com a fumaça da glória de Deus, e do seu poder; e ninguém podia entrar no templo, enquanto as sete pragas dos sete anjos não estivessem completas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 1, 'E eu ouvi uma grande voz do templo, dizendo aos sete anjos: “Ide, e derramai as taças da ira de Deus sobre a terra.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 2, 'E foi o primeiro, e derramou sua taça sobre a terra; e se fez uma chaga ruim e maligna nos homens que tinham a marca da besta, e que adoravam a imagem dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 3, 'E o segundo anjo derramou sua taça sobre o mar, e [este] se tornou em sangue como de morto, e toda alma vivente no mar morreu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 4, 'E o terceiro anjo derramou sua taça sobre os rios, e sobre as fontes de águas, e se tornaram em sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 5, 'E eu ouvi ao anjo das águas, dizendo: “Justo és tu, Senhor, que és, e que eras, e que virás a ser, porque julgaste estas coisas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 6, 'porque eles derramaram o sangue dos santos e dos profetas, também tu lhes deste sangue a beber; porque disto são merecedores.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 7, 'E ouvi um outro do altar, dizendo: “Sim, Senhor Deus Todo-Poderoso, verdadeiros e justos são os teus juízos!”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 8, 'E o quarto anjo derramou sua taça sobre o sol; e foi-lhe concedido que queimasse os seres humanos com fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 9, 'E os seres humanos foram queimados com grande calor, e blasfemaram do nome de Deus, que tem poder sobre estas pagas; e eles não se arrependeram, para lhe darem glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 10, 'E o quinto anjo derramou sua taça sobre o trono da besta, e seu reino se tornou em trevas, e mordiam de dor suas línguas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 11, 'E eles blasfemaram a Deus do céu por causa de suas dores e por causa de suas chagas; e não se arrependeram de suas obras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 12, 'E o sexto anjo derramou sua taça sobre o grande rio Eufrates; e sua água se secou, para que se preparasse o caminho dos reis do [oriente] , onde o sol nasce.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 13, 'E da boca do dragão, e da boca da besta, e da boca do falso profeta, eu vi [saírem] três espíritos imundos, semelhantes a rãs.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 14, 'Porque são espíritos de demônios, e fazem sinais sobrenaturais, os quais vão aos reis da terra, e de todo o mundo, para os ajuntarem à batalha daquele grande dia do Deus Todo-Poderoso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 15, '“(Eis que eu venho como ladrão. Bendito é aquele que vigia e guarda suas roupas, para que não ande nu, e vejam seu impudor).”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 16, 'E foram reunidos no lugar que em hebraico se chama Armagedom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 17, 'E o sétimo anjo derramou sua taça sobre o ar; e saiu uma grande voz do templo do céu, do trono, dizendo: “Está feito.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 18, 'E houve vozes, e trovões, e relâmpagos; e houve um grande terremoto, o qual nunca tinha acontecido desde que existia a humanidade sobre a terra, de tão forte e tão grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 19, 'E a grande cidade se fendeu em três partes, e as cidades das nações caíram; e a grande Babilônia veio em memória diante de Deus, para dar a ela o cálice do vinho da indignação da sua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 20, 'E toda ilha fugiu, e os montes não foram achados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 16, 21, 'E uma grande granizo, como de peso de um talento, caiu do céu sobre os homens; e os seres humanos blasfemaram a Deus por causa da praga do granizo, porque a sua praga era muito grande.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 1, 'E veio um dos sete anjos que tinham as sete taças, e falou comigo, dizendo-me: “Vem, eu te mostrarei a condenação da grande prostituta, que está sentada sobre muitas águas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 2, 'com a qual os reis da terra se prostituíram, e os que habitam na terra se embriagaram com o vinho da sua prostituição.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 3, 'E ele me levou em espírito a um deserto, e eu vi uma mulher assentada sobre uma besta de cor de escarlate, que estava cheio de nomes de blasfêmia. E ele tinha sete cabeças e dez chifres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 4, 'E a mulher estava vestida de púrpura e de escarlate, e adorada com ouro, pedras preciosas, e pérolas; e em sua mão tinha um cálice de ouro cheio das abominações e da impureza de sua prostituição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 5, 'E na testa dela estava escrito um nome: “Mistério: A grande Babilônia, a mãe das prostituições e abominações da terra”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 6, 'E vi que a mulher estava bêbada do sangue dos santos, e do sangue das testemunhas de Jesus. E eu, ao vê-la, fiquei maravilhado com grande espanto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 7, 'E o anjo me disse: “Por que tu ficaste maravilhado? Eu te direi o mistério da mulher, e da besta que a traz, a qual tem as sete cabeças e os dez chifres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 8, 'A besta que tu viste, era, e não é; e está para subir do abismo, e irá para a perdição; e os que habitam sobre a terra (cujos nomes não estão escritos no livro da vida desde a fundação do mundo), ficarão maravilhados ao verem a besta que era, e não é, e ainda é.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 9, 'Aqui [está] o entendimento que tem sabedoria: as sete cabeças são sete montes, sobre os quais a mulher está sentada;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 10, 'E [também] são sete reis, os cinco são caídos; e um é, o outro ainda não chegou; e quando chegar, é necessário que ele continue por um pouco [de tempo] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 11, 'E a besta que era, e não é, este é também o oitavo; e é um dos sete, e vai para a perdição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 12, 'E os dez chifres que tu viste são dez reis, que ainda não receberam o reino; mas receberão autoridade como reis por uma hora, [juntamente] com a besta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 13, 'Estes têm uma mesma intenção, e entregarão seu poder e autoridade à besta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 14, 'Estes batalharão contra o Cordeiro, e o Cordeiro os vencerá, porque ele é o Senhor dos senhores, e o Rei dos reis); e os que estão com ele [são] os chamados, escolhidos, e fiéis.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 15, 'E ele me disse: “As águas que viste, onde a prostituta está sentada, são povos, multidões, nações e línguas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 16, 'E os dez chifres que tu viste na besta, estes odiarão a prostituta, e a farão desolada, e nua; e comerão a carne dela, e a queimarão com fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 17, 'Porque Deus deu em seus corações que cumpram a intenção dele, e tenham uma mesma intenção, e deem o reino deles à besta, até que as palavras de Deus se cumpram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 17, 18, 'E a mulher que tu viste é a grande cidade, que tem o reinado sobre os reis da terra.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 1, 'E depois destas coisas eu vi outro anjo descendo do céu, tendo grande poder; e a terra foi iluminada pela sua glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 2, 'E ele clamou fortemente em alta voz, dizendo: “Caiu! Caiu a grande Babilônia, e ela se tornou habitação de demônios, e prisão de todo espírito imundo, e prisão de toda ave impura e odiável;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 3, 'porque todas as nações têm bebido do vinho da ira da prostituição dela, e os reis da terra se prostituíram com ela, e os comerciantes da terra se enriqueceram com o poder da sensualidade dela.”'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 4, 'E eu ouvi outra voz do céu, dizendo: “Saí dela, povo meu! Para que não sejais participantes dos pecados dela, e para que não recebais das pragas dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 5, 'Porque os pecados dela se acumularam até o céu, e Deus se lembrou das maldades dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 66, 'Apocalipse', 'Ap', 18, 6, 'Retribuí a ela assim como ela tem vos retribuído, e duplicai a ela em dobro, conforme as obras dela; no cálice em que ela preparou, preparai em dobro para ela.')
